from pathlib import Path
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,PageBreak,Table,TableStyle,KeepTogether
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import A4
out=Path('output/pdf');out.mkdir(parents=True,exist_ok=True)
p=out/'RF1-Registry-Training-Correction-Plan-Shelbi-2026-11-12.pdf'
styles=getSampleStyleSheet();olive=colors.HexColor('#52632d');ink=colors.HexColor('#263021');muted=colors.HexColor('#60685b')
styles.add(ParagraphStyle(name='TitleRF',fontName='Helvetica-Bold',fontSize=25,leading=29,textColor=ink,spaceAfter=15))
styles.add(ParagraphStyle(name='SubRF',fontName='Helvetica',fontSize=10,leading=15,textColor=muted,spaceAfter=16))
styles.add(ParagraphStyle(name='HeadRF',fontName='Helvetica-Bold',fontSize=15,leading=19,textColor=olive,spaceAfter=10,spaceBefore=12))
styles.add(ParagraphStyle(name='BodyRF',fontName='Helvetica',fontSize=10.5,leading=15.5,textColor=ink,spaceAfter=10))
styles.add(ParagraphStyle(name='ItemRF',fontName='Helvetica-Bold',fontSize=11.5,leading=15,textColor=olive,spaceAfter=5))
styles.add(ParagraphStyle(name='SmallRF',fontName='Helvetica',fontSize=9,leading=12.5,textColor=muted,spaceAfter=8))
def para(t,style='BodyRF'):return Paragraph(t,styles[style])
def item(n,title,body):return KeepTogether([para(str(n)+'. '+title,'ItemRF'),para(body),Spacer(1,7)])
story=[para('Registry &amp; Training<br/>Correction Plan','TitleRF'),para('For Shelbi | RF-One Product Owner briefing | November 12, 2026','SubRF'),para('Assessment: an implementation-quality failure','HeadRF'),para('At this point, we have concrete grounds to question the quality and completeness of the implementation produced with Claude. The concern is supported by identifiable software defects, rather than by frustration with response times alone.'),para('Registry repeatedly resolved the same account-to-person links and loaded People data even when users opened other tabs. The Clover reconciliation queue added repeated historical-data scans. These are implementation inefficiencies that should have been detected before release.'),para('This evidence supports an assessment of poor implementation and insufficient verification in this work. It does <b>not</b> establish a general malfunction of Claude as a product, or prove that every defect came from one author. Attribution requires reviewing the relevant changes and their history.'),para('Measured evidence','HeadRF')]
data=[[para('Local fixture','SmallRF'),para('Before','SmallRF'),para('After','SmallRF')],[para('People - SQL queries','SmallRF'),'8,962','160'],[para('People - response time','SmallRF'),'5.04 s','0.28 s'],[para('Roles - SQL queries','SmallRF'),'8,950','17'],[para('Roles - response time','SmallRF'),'5.73 s','0.014 s']]
t=Table(data,colWidths=[265,95,95],hAlign='LEFT');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#edf0e3')),('TEXTCOLOR',(0,0),(-1,-1),ink),('FONTNAME',(1,1),(-1,-1),'Helvetica'),('FONTSIZE',(1,1),(-1,-1),10),('VALIGN',(0,0),(-1,-1),'TOP'),('BOTTOMPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),7),('LINEBELOW',(0,0),(-1,-1),0.4,colors.HexColor('#d9dfcc'))]));story += [t,Spacer(1,10),para('Same disposable local fixture, with 40 additional linked people/accounts. These are local measurements, not guaranteed AWS timings. People HTML was identical before and after.','SmallRF'),para('AWS checks found the Web service running and no sign of CPU or memory saturation in the inspected metrics. Service-wide latency spikes were observed, but were not attributable to Registry alone. The performance correction is undergoing the separately authorized release process; this document does not certify deployment completion.','SmallRF'),PageBreak(),para('Proposed corrections: identity and access','TitleRF'),para('Items 1-12 are the broader correction proposal. They have not all been implemented or published.','SubRF')]
items=[('Define and use one canonical person identity','Clarify the relationship between People Directory and Registry. Employee, student and external-participant records must refer to the same person, without creating independent directories.'),('Reconcile existing identity links','Identify duplicate Training identities, disconnected RF1 accounts and assignments linked to the wrong person. Preserve all history. Ambiguous matches require explicit confirmation; names alone are not enough.'),('Unify Training enrollment and access enablement','When Training access is granted, reuse or create its technical Training identity and complete the link to the RF1 account. An authorized user must not remain blocked by an incomplete identity link.'),('Select recipients from the central directory','Training should select eligible employees and external participants from shared identity records. Dismissed people remain available in authorized historical views but cannot receive new assignments.'),('Enforce company boundaries on recipients','A trainer may list, inspect and manage only recipients within the authorized company scope. Recheck the same scope when saving, including direct endpoint requests and pages opened before a permission change.'),('Use Registry permissions throughout Training','Apply effective Registry permissions to every Training operation. Stop using a stale stored Training role to decide whether an assignment is allowed. Support different roles in different companies.')]
for n,(title,body) in enumerate(items,1):story.append(item(n,title,body))
story += [PageBreak(),para('Proposed corrections: ownership and control','TitleRF'),para('Preserve learning history while removing duplicate sources of identity and authority.','SubRF')]
items2=[('Show where permissions come from','Display direct grants and all contributing roles. Removing one role does not revoke access if another grant still provides it. Administrators need to see the complete explanation.'),('Centralize names, email addresses and phone numbers','Training should read shared personal information and retain only training-specific data. Distinguish verified login email from contact email, and label any historical snapshots clearly.'),('Separate archiving, dismissal and account suspension','Archiving a Training student must not implicitly disable access to the whole platform. Employment dismissal, Training participation and RF1 account suspension need separate effects and explicit authority.'),('Retire obsolete Training credentials and login paths','Keep one RF1 login. Remove redundant Training password-management mechanisms only after confirming that existing identities, assignments and results remain accessible.'),('Restore the meaning of training needs','Record why content is assigned. Where available, connect the need to a role, position or gap identified in Selection. Keep manual individual assignments available.'),('Align documentation, classification and verification','Clarify Training as an internal service, update deployment records and verify behavior against the actual release. Test grants, revocations, company boundaries, dismissed recipients, repeated enrollment and preservation of history.')]
for n,(title,body) in enumerate(items2,7):story.append(item(n,title,body))
story += [para('Release discipline','HeadRF'),para('The current performance patch changes presentation reads and queue retrieval, not authorization rules or business functions. Local workflow, permission-revocation and Clover-attribution checks passed. The broader identity and Training corrections require their own implementation, data audit and acceptance checks.','SmallRF')]
def footer(c,doc):
 w,h=A4;c.setStrokeColor(colors.HexColor('#d9dfcc'));c.line(48,43,w-48,43);c.setFont('Helvetica',8);c.setFillColor(muted);c.drawString(48,29,'RF-One | Registry & Training | Internal review');c.drawRightString(w-48,29,str(doc.page))
SimpleDocTemplate(str(p),pagesize=A4,rightMargin=48,leftMargin=48,topMargin=43,bottomMargin=57,title='RF1 Registry and Training - Correction Plan',author='RF-One Product Owner briefing').build(story,onFirstPage=footer,onLaterPages=footer)
print(p.resolve())
import fitz
r=fitz.open(p);print('Pages:',len(r));render=Path('tmp/pdfs/registry-correction-plan');render.mkdir(parents=True,exist_ok=True)
for i,page in enumerate(r):page.get_pixmap(matrix=fitz.Matrix(1.2,1.2)).save(str(render/f'page-{i+1}.png'))
